//! The [`Executor`], [`Database`] and [`Transaction`] traits implemented by every
//! backend.

use std::future::Future;
use std::pin::Pin;

use crate::ast::{InsertAst, Query};
use crate::error::Result;
use crate::model::Model;
use crate::row::FromRow;
use crate::schema::{Dialect, TableSchema};
use crate::value::Value;

/// Result of a statement that does not return rows.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ExecResult {
    /// Number of rows inserted, updated or deleted.
    pub rows_affected: u64,
    /// Primary key generated by an insert, when there is one.
    pub last_insert_id: Option<Value>,
}

/// Something that can run statements: a database handle or a transaction.
///
/// All query builders and model methods take `&impl Executor`, so the same code
/// works with [`MemoryDb`](crate::MemoryDb), `SqliteDb`, `PgPool` and their
/// transactions.
pub trait Executor: Send + Sync {
    /// SQL dialect spoken by the backend (`None` for the memory engine).
    fn dialect(&self) -> Option<Dialect>;

    /// Runs a statement returning rows and decodes every row into `O`.
    fn fetch_all<O>(&self, query: Query<'_>) -> impl Future<Output = Result<Vec<O>>> + Send
    where
        O: FromRow + Send;

    /// Runs a statement that does not return rows.
    fn execute(&self, query: Query<'_>) -> impl Future<Output = Result<ExecResult>> + Send;

    /// `CREATE TABLE` (and its indexes) for a model.
    fn create_table<M: Model>(&self) -> impl Future<Output = Result<()>> + Send {
        async move {
            self.execute(Query::CreateTable { table: M::SCHEMA, if_not_exists: false }).await?;
            Ok(())
        }
    }

    /// `CREATE TABLE IF NOT EXISTS` (and its indexes) for a model.
    fn create_table_if_not_exists<M: Model>(&self) -> impl Future<Output = Result<()>> + Send {
        async move {
            self.execute(Query::CreateTable { table: M::SCHEMA, if_not_exists: true }).await?;
            Ok(())
        }
    }

    /// Brings the model's table up to date, like `drizzle-kit push` or
    /// `prisma db push`, without migration files: creates the table if it is
    /// missing, otherwise adds the columns and indexes added to the model
    /// since. Nothing is ever dropped, renamed or retyped, and a column that
    /// existing rows could not fill (not an `Option`, no `default`) is refused
    /// before anything changes. Running it again changes nothing.
    ///
    /// ```
    /// # use memoire_orm::prelude::*;
    /// # #[derive(Model, Debug, Clone)]
    /// # struct User { #[memoire(primary_key, auto_increment)] id: i64, name: String }
    /// # async fn demo() -> memoire_orm::Result<()> {
    /// let db = MemoryDb::new();
    /// let report = db.push::<User>().await?;
    /// assert!(report.created);
    /// assert!(db.push::<User>().await?.is_unchanged());
    /// # Ok(()) }
    /// ```
    fn push<M: Model>(&self) -> impl Future<Output = Result<crate::push::PushReport>> + Send {
        crate::push::push::<Self, M>(self)
    }

    /// `DROP TABLE` for a model.
    fn drop_table<M: Model>(&self) -> impl Future<Output = Result<()>> + Send {
        async move {
            self.execute(Query::DropTable { name: M::SCHEMA.name, if_exists: false }).await?;
            Ok(())
        }
    }

    /// `DROP TABLE IF EXISTS` for a model.
    fn drop_table_if_exists<M: Model>(&self) -> impl Future<Output = Result<()>> + Send {
        async move {
            self.execute(Query::DropTable { name: M::SCHEMA.name, if_exists: true }).await?;
            Ok(())
        }
    }

    /// Runs raw SQL returning rows (SQL backends only).
    ///
    /// Placeholders follow the database syntax (`$1` on PostgreSQL, `?` on
    /// SQLite). Rows are decoded by position into `O`.
    fn raw<O>(&self, sql: &str, params: &[Value]) -> impl Future<Output = Result<Vec<O>>> + Send
    where
        O: FromRow + Send,
    {
        async move { self.fetch_all(Query::Raw { sql, params }).await }
    }

    /// Runs raw SQL that does not return rows and returns the affected row count.
    fn raw_execute(&self, sql: &str, params: &[Value]) -> impl Future<Output = Result<u64>> + Send {
        async move { Ok(self.execute(Query::Raw { sql, params }).await?.rows_affected) }
    }

    /// Inserts rows handed over by value, all or nothing; returns the number of
    /// rows inserted. Used by [`Model::insert_many`]. The default runs a
    /// multi-row `INSERT` ([`Query::Insert`]); the in-memory engine stores the
    /// values as they are, without copying them. Generated keys are not read back.
    fn insert_rows(
        &self,
        table: &'static TableSchema,
        rows: Vec<Vec<Value>>,
    ) -> impl Future<Output = Result<u64>> + Send {
        async move {
            let ast = InsertAst { table, rows };
            Ok(self.execute(Query::Insert(&ast)).await?.rows_affected)
        }
    }
}

/// A boxed future borrowing a transaction, returned by the closure given to
/// [`Database::transaction`]: write `Box::pin(async move { ... })`.
pub type BoxFuture<'a, T> = Pin<Box<dyn Future<Output = T> + Send + 'a>>;

/// How many times [`Database::transaction`] runs its closure at most.
pub const TRANSACTION_ATTEMPTS: u32 = 5;

/// A database handle that can open transactions.
pub trait Database: Executor {
    /// Transaction type.
    type Tx<'c>: Transaction
    where
        Self: 'c;

    /// Starts a transaction.
    ///
    /// The transaction is rolled back if it is dropped without calling
    /// [`Transaction::commit`].
    fn begin(&self) -> impl Future<Output = Result<Self::Tx<'_>>> + Send;

    /// Runs `f` in a transaction, like Prisma's `$transaction`: commits when
    /// it returns `Ok`, rolls back when it returns `Err` (or panics), and runs
    /// it again from the start when the database reports a conflict
    /// ([`Error::is_conflict`](crate::Error::is_conflict): a concurrent
    /// writer, a deadlock, a serialization failure, a busy SQLite file), up to
    /// [`TRANSACTION_ATTEMPTS`] times in all.
    ///
    /// Since `f` may run more than once, it reads what it needs inside the
    /// transaction. The future it returns may only borrow the transaction:
    /// it captures values (`move`, cloning a `String` or an `Arc` if needed),
    /// not references to local variables.
    ///
    /// ```
    /// # use memoire_orm::prelude::*;
    /// # #[derive(Model, Debug, Clone)]
    /// # struct Account { #[memoire(primary_key)] id: i64, balance: i64 }
    /// # async fn demo() -> memoire_orm::Result<()> {
    /// let db = MemoryDb::new();
    /// # db.create_table::<Account>().await?;
    /// # Account { id: 1, balance: 100 }.insert(&db).await?;
    /// # Account { id: 2, balance: 0 }.insert(&db).await?;
    /// let amount = 30;
    /// db.transaction(|tx| Box::pin(async move {
    ///     let mut from = Account::find(tx, 1).await?.ok_or(Error::NotFound)?;
    ///     let mut to = Account::find(tx, 2).await?.ok_or(Error::NotFound)?;
    ///     from.balance -= amount;
    ///     to.balance += amount;
    ///     from.update(tx).await?;
    ///     to.update(tx).await?;
    ///     Ok(())
    /// }))
    /// .await?;
    /// # Ok(()) }
    /// ```
    fn transaction<'c, T, F>(&'c self, mut f: F) -> impl Future<Output = Result<T>> + Send
    where
        Self: 'c,
        T: Send,
        F: for<'t> FnMut(&'t Self::Tx<'c>) -> BoxFuture<'t, Result<T>> + Send,
    {
        async move {
            let mut attempt = 1;
            loop {
                let tx = self.begin().await?;
                let outcome = match f(&tx).await {
                    Ok(value) => tx.commit().await.map(|()| value),
                    Err(e) => {
                        let _ = tx.rollback().await;
                        Err(e)
                    }
                };
                match outcome {
                    Err(e) if e.is_conflict() && attempt < TRANSACTION_ATTEMPTS => attempt += 1,
                    outcome => return outcome,
                }
            }
        }
    }
}

/// An open transaction. It is itself an [`Executor`].
pub trait Transaction: Executor {
    /// Makes every change permanent.
    fn commit(self) -> impl Future<Output = Result<()>> + Send;

    /// Discards every change.
    fn rollback(self) -> impl Future<Output = Result<()>> + Send;
}

/// A shared reference to an executor is an executor: wrappers such as
/// [`Observed`](crate::Observed) can borrow a handle instead of owning it.
impl<E: Executor + ?Sized> Executor for &E {
    fn dialect(&self) -> Option<Dialect> {
        (**self).dialect()
    }

    fn fetch_all<O>(&self, query: Query<'_>) -> impl Future<Output = Result<Vec<O>>> + Send
    where
        O: FromRow + Send,
    {
        (**self).fetch_all(query)
    }

    fn execute(&self, query: Query<'_>) -> impl Future<Output = Result<ExecResult>> + Send {
        (**self).execute(query)
    }

    fn insert_rows(
        &self,
        table: &'static TableSchema,
        rows: Vec<Vec<Value>>,
    ) -> impl Future<Output = Result<u64>> + Send {
        (**self).insert_rows(table, rows)
    }
}

impl<D: Database> Database for &D {
    type Tx<'c>
        = D::Tx<'c>
    where
        Self: 'c;

    fn begin(&self) -> impl Future<Output = Result<Self::Tx<'_>>> + Send {
        (**self).begin()
    }
}
